(async()=>{
 const root=document.getElementById('extraction-review'),make=(tag,text,cls)=>{const e=document.createElement(tag);if(text)e.textContent=text;if(cls)e.className=cls;return e};
 try{const r=await fetch('extraction-data/audit.json');if(!r.ok)throw Error();const d=await r.json();const controls=make('div',null,'controls'),rl=make('label','Extraction repeat'),run=make('select'),cl=make('label','Focal claim'),claim=make('select');run.id='extraction-repeat';claim.id='extraction-claim';d.runs.forEach((r,i)=>{const o=make('option',`Repeat ${r.repeat} · stopped at token limit`);o.value=i;run.append(o)});d.reference.forEach(r=>{const o=make('option',`${r.id} · ${r.label}`);o.value=r.id;claim.append(o)});rl.append(run);cl.append(claim);controls.append(rl,cl);const body=make('div');root.append(controls,body);
 function show(){const r=d.runs[Number(run.value)],ref=d.reference.find(r=>r.id===claim.value),card=r.cards.find(c=>c.reference_id===ref.id);body.replaceChildren();body.append(make('h3',ref.label),make('p',card?(card.review==='unresolved_truncation'?'Unresolved: output stops partway through this card.':'Provisionally faithful core content · unblinded assistant review'):'Absent from delivered output','extraction-label'));
 const cols=make('div',null,'extraction-comparison'),source=make('div'),output=make('div');source.append(make('h3','Actual input paragraphs'));for(const s of ref.source_spans){source.append(make('p',s.person,'small'),make('blockquote',s.quote))}output.append(make('h3','Actual delivered extraction'));if(card){output.append(make('p',card.rationale));const pre=make('pre',card.full_card);output.append(pre)}else output.append(make('p','No matching focal claim card was delivered. This is an omission in the received output; truncation prevents attributing it solely to the extraction procedure.'));cols.append(source,output);body.append(cols);const full=make('details');full.append(make('summary','Full native input/output and termination metadata'));const info=make('pre',`Model: ${r.model}\nCompletion tokens: ${r.completion_tokens} / ${r.max_output_tokens}\nFinish reason: ${r.finish_reason}\nRun: ${r.run_id}`);full.append(info,make('h3','Original request'),make('pre',r.request.messages.map(m=>`${m.role.toUpperCase()}\n${m.content}`).join('\n\n')),make('h3','Saved output'),make('pre',r.output));body.append(full)}
 run.onchange=show;claim.onchange=show;show();
 }catch(e){root.textContent='The saved audit could not load. Download the audit JSON below to inspect its records.'}
})();
